import{_ as e,o,c as r,af as t}from"./chunks/framework.D75dE8dq.js";const u=JSON.parse('{"title":"第2章 Trae 项目构建与功能了解","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"pages/trae/01/02.md","filePath":"pages/trae/01/02.md","lastUpdated":null}'),d={name:"pages/trae/01/02.md"};function i(c,a,l,h,p,n){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="第2章-trae-项目构建与功能了解" tabindex="-1">第2章 Trae 项目构建与功能了解 <a class="header-anchor" href="#第2章-trae-项目构建与功能了解" aria-label="Permalink to &quot;第2章 Trae 项目构建与功能了解&quot;">​</a></h1><h2 id="_1-项目管理" tabindex="-1">1. 项目管理 <a class="header-anchor" href="#_1-项目管理" aria-label="Permalink to &quot;1. 项目管理&quot;">​</a></h2><p>你可以管理 Trae IDE 中的项目，包括创建项目和切换项目。</p><h3 id="_1-1-什么是-工作空间" tabindex="-1">1.1 什么是 “工作空间”？ <a class="header-anchor" href="#_1-1-什么是-工作空间" aria-label="Permalink to &quot;1.1 什么是 “工作空间”？&quot;">​</a></h3><p><code>工作空间</code>通常为一个在 Trae 中打开的文件夹。若你的项目较为复杂，也可以将多个文件夹添加至一个 “工作空间”。</p><h3 id="_1-2-创建项目" tabindex="-1">1.2 创建项目 <a class="header-anchor" href="#_1-2-创建项目" aria-label="Permalink to &quot;1.2  创建项目&quot;">​</a></h3><p>Trae 提供三种创建项目的方式：导入本地文件夹、从 GitHub 克隆仓库、从 Git 仓库的 URL 克隆。</p><h4 id="方式一-导入本地文件" tabindex="-1">方式一：导入本地文件 <a class="header-anchor" href="#方式一-导入本地文件" aria-label="Permalink to &quot;方式一：导入本地文件&quot;">​</a></h4><p>（1）点击左侧面板中央的 打开文件夹 按钮，或在界面左上角点击 选择项目 &gt; 打开文件夹。</p><p>（2） 选择文件夹并在 Trae 中将其打开，你将看到授权弹窗</p><p>（3） 根据提示完成授权：文件夹已在 IDE 中打开，你可以开始编辑项目。</p><h4 id="方式二-从-github-克隆仓库" tabindex="-1">方式二：从 GitHub 克隆仓库 <a class="header-anchor" href="#方式二-从-github-克隆仓库" aria-label="Permalink to &quot;方式二：从 GitHub 克隆仓库&quot;">​</a></h4><p>（1）点击左侧面板中央的 克隆 Git 仓库 按钮，或在界面左上角点击 选择项目 &gt; 克隆 Git 仓库。</p><p>（2） 点击 从 GitHub 克隆。</p><p>（3） 授权 GitHub 登录 Trae：点击 允许。 点击 复制并继续访问 GitHub。 点击 打开。你将前往 GitHub 上的登录授权页面。根据页面提示，完成授权。</p><p>（4） 返回 Trae。 弹框中展示可克隆的仓库列表。</p><p>（5） 直接从列表中选择一个仓库。 或 输入期望克隆的仓库名称，然后点击 从 GitHub 克隆。</p><p>（6） 在弹窗中，选择该仓库的存储位置，然后点击 选择为存储库目标。 Trae 开始克隆该仓库。克隆完毕后，你会看到弹窗。</p><p>（7） 按需从以下操作中选择其一： 点击 打开，直接在 Trae 的当前窗口打开该仓库。 点击 在新窗口中打开，在 Trae 中用新窗口中打开该仓库。</p><p>（8） 根据提示完成授权。 仓库已在 IDE 中打开，你可以开始编辑项目。</p><h4 id="方式三-直接从-git-仓库的-url-克隆-此方式无需授权-github-登录-trae-你可以直接使用目标仓库的-url-来将其克隆至-trae。" tabindex="-1">方式三：直接从 Git 仓库的 URL 克隆 此方式无需授权 GitHub 登录 Trae，你可以直接使用目标仓库的 URL 来将其克隆至 Trae。 <a class="header-anchor" href="#方式三-直接从-git-仓库的-url-克隆-此方式无需授权-github-登录-trae-你可以直接使用目标仓库的-url-来将其克隆至-trae。" aria-label="Permalink to &quot;方式三：直接从 Git 仓库的 URL 克隆  此方式无需授权 GitHub 登录 Trae，你可以直接使用目标仓库的 URL 来将其克隆至 Trae。&quot;">​</a></h4><p>（1）点击左侧面板中央的 克隆 Git 仓库 按钮，或在界面左上角点击 选择项目 &gt;克隆 Git 仓库。</p><p>（2） 在 URL 输入框中，输入目标 Git 仓库的 URL，然后点击 存储库 URL {URL}。</p><p>（3） 在弹窗中选择该仓库的存储地址，然后点击 选择为存储库目标。 Trae 开始克隆该仓库。</p><p>（4） 按需从以下操作中选择其一： 点击 打开，直接在 Trae 的当前窗口打开该仓库。 点击 在新窗口打开，在 Trae 中用新窗口中打开该仓库。</p><p>（5） 根据提示完成授权。 仓库已在 IDE 中打开，你可以开始编辑项目。</p><h3 id="_1-3-切换项目" tabindex="-1">1.3 切换项目 <a class="header-anchor" href="#_1-3-切换项目" aria-label="Permalink to &quot;1.3   切换项目&quot;">​</a></h3><p>当 Trae 中存在多个项目时，你可以切换不同的项目进行开发。</p><p>（1）在界面左上角，点击当前项目的名称。 界面上显示面板，展示最近导入或使用的项目列表。</p><p>（2） 在 最近列表中，选择需打开的项目。 Trae 打开一个新的窗口，加载并展示该项目。</p><h2 id="_2-侧边对话" tabindex="-1">2. 侧边对话 <a class="header-anchor" href="#_2-侧边对话" aria-label="Permalink to &quot;2. 侧边对话&quot;">​</a></h2><p>编码过程中，你可以随时在侧边对话框中与 AI 助手对话，包括回答编码问题、讲解代码仓库、生成代码片段、修复错误等。</p><h3 id="_2-1-打开侧边对话框" tabindex="-1">2.1 打开侧边对话框 <a class="header-anchor" href="#_2-1-打开侧边对话框" aria-label="Permalink to &quot;2.1 打开侧边对话框&quot;">​</a></h3><p>进入 <code>Trae IDE</code> 后，一般已默认打开侧边对话框。若非如此，你可以使用快捷键（macOS：<code>Command + U</code>；Windows：<code>Ctrl + U</code>）将其打开。</p><h3 id="_2-2-更多功能" tabindex="-1">2.2 更多功能 <a class="header-anchor" href="#_2-2-更多功能" aria-label="Permalink to &quot;2.2 更多功能&quot;">​</a></h3><p><code>Trae IDE</code> 提供一系列可以在对话中使用的功能，助力你更高效地开发项目。</p><h3 id="_2-3-自定义模型" tabindex="-1">2.3 自定义模型 <a class="header-anchor" href="#_2-3-自定义模型" aria-label="Permalink to &quot;2.3 自定义模型&quot;">​</a></h3><p>Trae 预置了一系列业内表现比较出色的模型，你可以直接切换不同的模型进行使用。此外，Trae 还支持通过 API 密钥（<code>API Key</code>）接入自定义模型，从而满足个性化的需求。</p><h3 id="_2-4-智能体" tabindex="-1">2.4 智能体 <a class="header-anchor" href="#_2-4-智能体" aria-label="Permalink to &quot;2.4 智能体&quot;">​</a></h3><p>智能体是你面向不同开发场景的编程助手。除内置的智能体 <code>Builder</code> 外，你还可以创建自定义智能体，通过灵活配置提示词和工具集，使其更高效地帮你完成复杂任务。</p><h3 id="_2-5-上下文" tabindex="-1">2.5 上下文 <a class="header-anchor" href="#_2-5-上下文" aria-label="Permalink to &quot;2.5 上下文&quot;">​</a></h3><p>AI 助手可以理解当前项目中的上下文，包括代码、文件、文件夹和整个工作空间，从而更精确地协助你完成开发需求。</p><h3 id="_2-6-生成并处理代码变更" tabindex="-1">2.6 生成并处理代码变更 <a class="header-anchor" href="#_2-6-生成并处理代码变更" aria-label="Permalink to &quot;2.6 生成并处理代码变更&quot;">​</a></h3><p><code>Chat</code> 模式下，根据你的需求，AI 助手会自动创建新文件或编辑已有文件并自动保存生成的代码。你可以接受或拒绝变更，包括：</p><p>若你选择接受代码变更，AI 助手会新建文件或将代码变更应用于已有的文件。应用的代码会以 <code>Diff</code> 的形式展示。</p><p><strong>处理多文件内的所有代码变更</strong>：点击输入框上方待审查文件列表中的 <code>全部接受</code> 或 <code>全部拒绝</code> 按钮，批量接受或拒绝当前项目中的所有代码变更。</p><p><strong>处理单文件内的所有代码变更</strong>：在编辑器内打开文件，点击上方提示条中的 <code>接受</code> 按钮（快捷键：macOS 为 <code>Command + Enter</code>；Windows 为 <code>Ctrl + Enter</code>）或 <code>拒绝</code> 按钮（快捷键：macOS 为 <code>Command + Backspace</code>；Windows 为 <code>Ctrl + Backspace</code>），批量接受或拒绝当前文件内的所有代码变更。</p><p><strong>处理单处代码变更</strong>：点击编辑器内某个代码变更右上角的 <code>^Y</code> 按钮（快捷键：macOS 为 <code>Control + Y</code>；Windows 为 <code>Alt + Y</code>）或 ^N 按钮（快捷键：macOS 为 <code>Control + N</code>；Windows 为 <code>Alt + N</code>），接受或拒绝该变更。</p><h3 id="_2-7-生成并运行命令" tabindex="-1">2.7 生成并运行命令 <a class="header-anchor" href="#_2-7-生成并运行命令" aria-label="Permalink to &quot;2.7 生成并运行命令&quot;">​</a></h3><p>对话过程中，根据你的需求，AI 助手会提供可一键运行的 <code>Shell</code> 命令。</p><h3 id="_2-8-管理历史对话" tabindex="-1">2.8 管理历史对话 <a class="header-anchor" href="#_2-8-管理历史对话" aria-label="Permalink to &quot;2.8 管理历史对话&quot;">​</a></h3><p>点击 AI 对话窗口右上角的 <code>历史会话</code> 按钮，查看并管理你与 AI 助手的所有对话。</p><p>若你需要查看某轮历史对话，点击该对话，你会跳转至该对话的位置。</p><p>若需要删除某轮对话，可以将鼠标悬浮至该对话，然后点击右侧的 <code>删除</code> 图标。对话被删除后无法恢复。</p>',54)])])}const b=e(d,[["render",i]]);export{u as __pageData,b as default};
